import{_ as l,C as e,o as s,c as n,E as a,a2 as o}from"./chunks/framework.uPk2SrVb.js";const x=JSON.parse('{"title":"同样的接受概率，为什么更多采购线程可能更差？","description":"","frontmatter":{"title":"同样的接受概率，为什么更多采购线程可能更差？","date":"2026-11-03","column":"industry-architecture","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"边际接受率不变时，共享接受风险如何改变并发采购收益？","summary":"一个保持边际接受率不变的内部模型反例，说明采购并发收益依赖分支相关性与重复接受成本，不能由信息处理加速推断。","sources":["https://arxiv.org/html/2610.06017v1","https://arxiv.org/html/2610.17206v1"],"pageClass":"runtime-v6-article","item_id":"SIG-20261103-005","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-03-sig-20261103-005-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-11-03-sig-20261103-005.md","filePath":"zh/industry/2026-11-03-sig-20261103-005.md","lastUpdated":null}'),d={name:"zh/industry/2026-11-03-sig-20261103-005.md"};function h(p,t,c,g,u,m){const r=e("ArticleCover"),i=e("ArticleTableScroll");return s(),n("div",null,[a(r,{image:"/assets/covers/daily-2026-11-03-sig-20261103-005-cover.png",kicker:"研究成果",title:"同样的接受概率，为什么更多采购线程可能更差？",summary:"一个保持边际接受率不变的内部模型反例，说明采购并发收益依赖分支相关性与重复接受成本，不能由信息处理加速推断。",version:"2026-11-03",languageHref:"/en/industry/2026-11-03-sig-20261103-005",languageLabel:"English"}),a(i,{language:"zh"}),t[0]||(t[0]=o('<h1 id="同样的接受概率-为什么更多采购线程可能更差" tabindex="-1">同样的接受概率，为什么更多采购线程可能更差？ <a class="header-anchor" href="#同样的接受概率-为什么更多采购线程可能更差" aria-label="Permalink to &quot;同样的接受概率，为什么更多采购线程可能更差？&quot;">​</a></h1><p>在本次内部模型实验中，同一组十四条采购线程，按独立接受规划时的期望收益为 0.518956；只把分支改成完全相关，保持每条线程的接受概率和价格上限不变，收益就变为 −0.283656。更多分支的价值，取决于它们能否分散风险，而不只取决于每条分支是否“同样可靠”。设计采购智能体的工程师需要检查的，是至少一次接受与重复接受如何同时变化。</p><h2 id="接受率相同-不代表分散收益相同" tabindex="-1">接受率相同，不代表分散收益相同 <a class="header-anchor" href="#接受率相同-不代表分散收益相同" aria-label="Permalink to &quot;接受率相同，不代表分散收益相同&quot;">​</a></h2><p>Cano（并发感知谈判优化器）论文研究单件采购、单个硬截止窗口及共同价格上限。它把采购失败损失、每条线程成本和超额接受成本一起计入目标，并假设最终承诺管理器最多保留一笔有约束力的交易。<a href="https://arxiv.org/html/2610.06017v1" target="_blank" rel="noreferrer">论文第 2.3、3 节</a>描述的是模型及系统职责，不是已运行的交易执行保障。</p><p>设启动线程数为 m，每条接受概率为 q，接受数为 K（接受总数）。独立时，至少一次接受的概率记作 S（至少一次接受概率），有 S=1−(1−q)^m；若所有线程共享一次接受事件，则 S=q。两种情况下，期望接受数都为 mq，但期望超额接受数为 mq−S，因此并不相同。</p><p>用论文中的 V（价值）、L（失败损失）、线程成本 κ、超额接受成本 δ 和共同价格上限 b(q)，本次复算的目标写为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>期望收益 = (V + L + δ − b(q)) S − L − κm − δmq</span></span></code></pre></div><p>这不是在给真实卖家估计风险。完全相关只是一个刻意构造的边界：它让我们在不改变单线程边际接受率的条件下，看清独立性前提的作用。即使最后只允许一笔交易，其他暂时接受仍可能产生取消或机会成本；模型没有把这些成本自动消除。</p><h2 id="三种策略-三种不同的问题" tabindex="-1">三种策略，三种不同的问题 <a class="header-anchor" href="#三种策略-三种不同的问题" aria-label="Permalink to &quot;三种策略，三种不同的问题&quot;">​</a></h2><p>同日分析阶段采用归一化市场参数 V=1.4、L=0.2、κ=0.01、δ=0.05，最多二十条线程；均匀价格分布均值为 1、标准差为 0.35。按论文公式重新实现目标，在 q 步长 0.0001 的离散网格搜索，使用精确二项枚举，并以种子 20261103 模拟十万笔订单。这里报告已有分析结果，没有在写作阶段追加实验。</p><table tabindex="0"><thead><tr><th>条件</th><th style="text-align:right;">线程数 m</th><th style="text-align:right;">每条接受概率 q</th><th style="text-align:right;">期望收益</th><th>证据角色</th></tr></thead><tbody><tr><td>独立接受下的网格规划</td><td style="text-align:right;">14</td><td style="text-align:right;">0.151</td><td style="text-align:right;">0.518956</td><td>内部公式复算</td></tr><tr><td>原策略改为完全相关接受</td><td style="text-align:right;">14</td><td style="text-align:right;">0.151</td><td style="text-align:right;">−0.283656</td><td>内部构造反例，其他参数不变</td></tr><tr><td>完全相关下重新规划</td><td style="text-align:right;">1</td><td style="text-align:right;">0.4974</td><td style="text-align:right;">0.090008</td><td>内部离散搜索，同时改变线程数与接受目标</td></tr></tbody></table><p>来源：同日内部实验原始输出，见文末实验数据。第三行不是保持 q 不变的比较，也不能把它与第二行的差异全部归因于减少线程。</p><p>独立条件下，十万次模拟均值为 0.520128，标准误为 0.000924；精确枚举为 0.5189564216185868，与解析目标相容。模拟中至少一次接受的频率为 0.89999，至少两次接受的频率为 0.646，平均超额接受数为 1.21375。这些是归一化模拟市场的内部结果，不是卖家履约数据或独立复现。</p><p>单线程接受率没有变化，却失去了“多试几次能互相补偿”的好处，线程成本和超额接受成本又继续支付，这正是固定策略变亏的机制。重新规划说明模型会改变选择；它不说明真实系统已经能识别这种相关性。</p><h2 id="信息汇总的加速回答不了采购承诺问题" tabindex="-1">信息汇总的加速回答不了采购承诺问题 <a class="header-anchor" href="#信息汇总的加速回答不了采购承诺问题" aria-label="Permalink to &quot;信息汇总的加速回答不了采购承诺问题&quot;">​</a></h2><p>AutoMARS（多智能体供应链风险分析系统）论文描述并行检索、报告合并和反思修订。作者报告每种设置十次运行，总耗时从串行的 622.11±59.84 秒降为并行的 327.49±64.70 秒。<a href="https://arxiv.org/html/2610.17206v1" target="_blank" rel="noreferrer">论文第 4、5.3.4 节</a>的这些结果属于来源陈述，本次没有复测，原始轨迹和独立计时依据也未在获准输入中确立。</p><p>生成信息的分支可以把结果合并；可能向外部作出承诺的分支还需要处理超额接受。两者的责任边界不同，耗时降低不能回答取消是否有效、是否只产生一笔最终义务，也不能替代采购收益目标。这项比较只划分问题，不形成跨论文性能排行。</p><h2 id="在用线程预算前-还缺哪些证据" tabindex="-1">在用线程预算前，还缺哪些证据 <a class="header-anchor" href="#在用线程预算前-还缺哪些证据" aria-label="Permalink to &quot;在用线程预算前，还缺哪些证据&quot;">​</a></h2><p>本次内部复算只支持指定目标下的模型反例。论文的相关系数 0.7 压力测试是另一项作者实验，本次完全相关构造没有复现它。离散网格最优也不是连续全局最优的证明。真实卖家未必完全相关，相关性和成本可能随报价、时间或策略改变。</p><p>因此，实际设计下一步应先明确：哪些分支只返回信息，哪些可能形成外部义务；线程预算使用了什么联合接受假设；超额接受成本由谁承担。再用可观测的接受数据检验敏感性，并另行测试实际的取消、最终提交与去重机制。这是由模型推得的研究检查方向，不是已核验的产品操作建议。</p><p>没有语言模型、卖家交互、付款、取消或承诺执行层参与本次实验。现在仍未回答的问题是：在相关接受可观测、取消规则已实现的条件下，怎样选择可用线程预算？</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本文将论文中的设计视为公开一手事实，将论文中的性能数字视为作者报告；两者都不自动构成独立验证。内部实验是本研究过程的有限复算，不是第三方复现。公开发表与引用确立来源关系，不能单凭这些状态推断理论普遍有效。</p><ul><li>《并行还是让步？面向智能体商务的并发感知采购谈判》（中文译名；作者：Xiaolin Xu、Donghao Zhu），2026-10-05，预印本第 1 版。<a href="https://arxiv.org/html/2610.06017v1" target="_blank" rel="noreferrer">模型与附录</a>。本文使用其单窗口目标，不声称复现完整论文。</li><li><em>AutoMARS</em>，2026-10，第 1 版预印本。<a href="https://arxiv.org/html/2610.17206v1" target="_blank" rel="noreferrer">系统设计及计时报告</a>。用于比较信息汇总与采购承诺的责任边界。</li><li>本研究中心，2026-11-03，<a href="/joinwell52/assets/evidence/2026-11-03-sig-20261103-005/experiment-data.json">内部实验数据</a>与<a href="/joinwell52/assets/evidence/2026-11-03-sig-20261103-005/experiment-source.json">对应公式复算源码</a>。数据保留网格、种子、标准误及边界；源码还包含同次分析的其他受限检查，本篇只使用采购实验结果。</li></ul>',24))])}const b=l(d,[["render",h]]);export{x as __pageData,b as default};
